def best_streak_profit(daily):
    # Largest total profit over any run of consecutive days, or 0 if every day is a loss
    best = 0
    current = 0
    for amount in daily:
        current = max(amount, current + amount)
        best = max(best, current)
    return best if best > 0 else max(daily)

def best_streak_profit(daily):
    if not daily:
        return 0
    best = max(daily)
    current = 0
    for amount in daily:
        current = max(amount, current + amount)
        best = max(best, current)
    return best

